import { api } from './authService';

const userService = {
  /** GET /users */
  getAll: async () => {
    const { data } = await api.get('/users');
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/users/${id}`);
    return data?.data ?? data;
  },

  /**
   * POST /auth/register  ← utilisé pour créer un utilisateur depuis l'admin
   *
   * FIX : UserController n'expose pas de POST /users.
   * La création passe par /auth/register (endpoint public de AuthController).
   * Le payload doit correspondre à RegisterRequest :
   *   { name, email, password, role, phone }
   */
  create: async (payload) => {
    const body = {
      name:     payload.name,
      email:    payload.email,
      password: payload.password,
      role:     payload.role?.toUpperCase(),   // ex: "admin" → "ADMIN"
      phone:    payload.phone || '',
    };
    const { data } = await api.post('/auth/register', body);
    return data?.data ?? data;
  },

  /**
   * PUT /users/{id}
   * Corps attendu par UpdateUserRequest : { name, email, role, phone }
   */
  update: async (id, payload) => {
    const body = {
      name:  payload.name,
      email: payload.email,
      role:  payload.role?.toUpperCase(),
      phone: payload.phone || '',
    };
    const { data } = await api.put(`/users/${id}`, body);
    return data?.data ?? data;
  },

  /**
   * PATCH /users/{id}/password
   * Corps attendu : { oldPassword, newPassword }
   * (admin flow : on passe un mot de passe fictif pour oldPassword si besoin)
   */
  changePassword: async (id, oldPassword, newPassword) => {
    const { data } = await api.patch(`/users/${id}/password`, { oldPassword, newPassword });
    return data?.data ?? data;
  },

  /**
   * PATCH /users/{id}/role  — non exposé dans UserController.
   * On réutilise PUT /users/{id} en ne changeant que le rôle.
   */
  updateRole: async (id, role) => {
    // On récupère l'utilisateur d'abord pour ne pas écraser les autres champs
    const user = await userService.getById(id);
    return userService.update(id, { ...user, role });
  },

  /** PATCH /users/{id}/deactivate */
  deactivate: async (id) => {
    const { data } = await api.patch(`/users/${id}/deactivate`);
    return data?.data ?? data;
  },

  /** PATCH /users/{id}/activate */
  activate: async (id) => {
    const { data } = await api.patch(`/users/${id}/activate`);
    return data?.data ?? data;
  },

  /** DELETE /users/{id} */
  delete: async (id) => {
    const { data } = await api.delete(`/users/${id}`);
    return data?.data ?? data;
  },
};

export default userService;
